const HAIR_REF_STYLES = [
  ['Puntas bicolor', 'Two-tone spikes', { cap: 'spiky', bang: 'messy', side: 4, back: 5, jag: 1 }],
  ['Capas abiertas', 'Layered curtains', { cap: 'volume', bang: 'curtain', side: 9, back: 13, jag: 1, layer: 1 }],
  ['Liso largo diagonal', 'Long straight fringe', { cap: 'round', bang: 'side', side: 14, back: 21 }],
  ['Coleta alta rizada', 'High curly ponytail', { cap: 'round', bang: 'side', side: 4, back: 0, tail: 'ref-curly' }],
  ['Ondas a los hombros', 'Shoulder waves', { cap: 'round', bang: 'side', side: 9, back: 11, wave: 1 }],
  ['Tirabuzones con flequillo', 'Ringlets with bangs', { cap: 'volume', bang: 'full', side: 13, back: 19, curl: 2, bw: 1.26 }],
  ['Ondas largas abiertas', 'Long open waves', { cap: 'round', bang: 'side', side: 14, back: 22, wave: 1, bw: 1.24 }],
  ['Dos trenzas bajas', 'Two low braids', { cap: 'round', bang: 'side', side: 4, back: 3, tail: 'ref-braids' }],
  ['Dos coletas onduladas', 'Low wavy twintails', { cap: 'round', bang: 'side', side: 4, back: 3, tail: 'ref-low' }],
  ['Moño lateral', 'Side bun', { cap: 'round', bang: 'side', side: 4, back: 3, tail: 'ref-bun' }],
  ['Melena hacia atrás', 'Swept-back long hair', { cap: 'swept', bang: 'none', side: 11, back: 23, bw: 1.14 }],
  ['Bob ondulado en capas', 'Layered wavy bob', { cap: 'round', bang: 'side', side: 7, back: 8, wave: 1, layer: 1, jag: 1 }],
  ['Bob liso diagonal', 'Straight side-fringe bob', { cap: 'round', bang: 'side', side: 7, back: 6, bw: 1.05 }],
];

HAIR_REF_STYLES.forEach(([es, en, spec], refHair) => {
  const style = { ...spec, n: L2(es, en), refHair };
  HS_F.push(style);
  HS_M.push(style);
});

function drawReferenceFringe(p, id, hx, hy, rx, ry, hair, second) {
  const rows = HAIR_REF_PIXELS[id];
  const palette = id === 0 ? hair.concat(second || HAIRS.blanco) : hair;
  const stepX = 17.05 / rx, stepY = 19.5 / ry;
  for (let dy = -25; dy < 26; dy++) {
    const row = rows[Math.round(57 + (dy - 3) * stepY)];
    if (!row) continue;
    for (let dx = -22; dx < 23; dx++) {
      const symbol = row[Math.round(38 + dx * stepX)];
      if (symbol && symbol !== '.') p.set(hx + dx, hy + dy, palette[Number(symbol)]);
    }
  }
}

function drawReferenceTails(p, type, hx, hy, direction, layer, sway, hair) {
  const up = direction === 'up', side = direction === 'left' || direction === 'right';
  if (layer !== (up ? 'front' : 'back')) return;
  const back = direction === 'right' ? -1 : 1;
  if (type === 'ref-bun') {
    p.ball(hx + (side ? back * 5 : up ? -6 : 6), hy - 8, 5, 4.5, hair);
    return;
  }
  if (type === 'ref-curly') {
    const x = hx + (side ? back * 7 : up ? -6 : 6);
    for (let k = 0; k < 4; k++) p.ball(x + (k % 2 ? 2 : 0) + sway * .3, hy - 8 + k * 4, 4, 3.5, hair);
    return;
  }
  for (const sign of (side ? [back] : [-1, 1])) {
    const x = hx + sign * (side ? 5 : 7);
    if (type === 'ref-low') {
      heroStrand(p, [[x, hy+3], [x+sign*3, hy+8], [x+sign*2+sway, hy+13], [x+sign*4+sway, hy+18]], 3, hair, 1);
    } else {
      for (let k = 0; k < 6; k++) p.ball(x + (k % 2 ? sign : 0) + sway * k / 6, hy+4+k*2, 2.3-k*.16, 1.8, hair);
      p.hl(x-1+sway, hy+16, 3, C('#a94563'));
    }
  }
}
